pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        // Restrict to valid inputs that the reference can handle
        vm.assume(receiver != address(0) && receiver != address(this));
        vm.assume(amount > 0 && amount <= address(c).balance);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Call sendTo as owner
        vm.prank(c.owner());
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount)
        );

        // Check that send succeeds exactly when receiver is an EOA or accepts Ether
        uint256 balanceAfter = address(c).balance;
        bool balanceDecreased = balanceAfter < balanceBefore;
        bool amountDeducted = balanceBefore - balanceAfter == amount;

        // The general rule: if the call succeeded, balance decreased by exactly amount;
        // if it failed, balance stayed the same.
        assertTrue(
            (success && balanceDecreased && amountDeducted) ||
            (!success && !balanceDecreased)
        );
    }
}

