pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0) && receiver != address(c) && address(c).balance >= amount);
        vm.assume(amount > 0 && amount <= address(this).balance);

        address owner = address(this);
        uint256 ownerBalBefore = owner.balance;
        uint256 receiverBalBefore = receiver.balance;
        uint256 contractBalBefore = address(c).balance;

        (bool success,) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));

        if (success) {
            uint256 ownerBalAfter = owner.balance;
            uint256 receiverBalAfter = receiver.balance;
            uint256 contractBalAfter = address(c).balance;

            // The total ether outside the contract (owner + receiver) should increase by exactly amount
            // because the owner pays for the gas and the transfer; but since we don't account gas precisely,
            // we check the simpler invariant: contract balance remains unchanged since it's a simple passthrough.
            assert(contractBalBefore == contractBalAfter);
        }
    }
}

